    R,C=len(g),len(g[0])
    for i in range(R):
        for j in range(C):
            if g[i][j]!=bg and (i,j) not in seen:
                col=g[i][j]; q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
